// Tests for the pre-commit/pre-push review gate and the reviewed commit/push wrappers (no model calls: `claude` is stubbed).
// Run: node --test scripts/precommit-review.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const scripts = path.dirname(fileURLToPath(import.meta.url));
const gate = path.join(scripts, "precommit-review-gate.mjs");

function runGate(command) {
  return spawnSync("node", [gate], { input: JSON.stringify({ tool_input: { command } }), encoding: "utf8" });
}

test("the gate blocks direct git commit and push in every spelling", () => {
  for (const command of [
    "git commit -m x",
    "git add -A && git commit -m x",
    "git -C ../other commit -m x",
    "git -c user.name=x commit -am x",
    "GIT_AUTHOR_NAME=x git commit -m x",
    "env FOO=1 git push origin HEAD",
    "/usr/bin/git push -u origin HEAD",
    "cd ../wt && git commit -m x",
    "sh -c 'git commit -m x'",
    "git merge origin/main && git push",
    "git commit -m x 2>&1",
  ]) assert.equal(runGate(command).status, 2, command);
});

test("the gate allows other commands and plain wrapper invocations", () => {
  for (const command of [
    "git status", "git diff --cached", "git log --oneline -5", "ls -la", "gh pr view 12",
    "scripts/commit-reviewed.sh -m 'docs: explain git push rules'",
    "bash scripts/push-reviewed.sh origin --set-upstream",
  ]) assert.equal(runGate(command).status, 0, command);
});

test("the gate does not let a wrapper name smuggle in a second command", () => {
  for (const command of [
    "scripts/commit-reviewed.sh -m x && git push origin HEAD",
    "scripts/push-reviewed.sh; git commit -m x",
    "scripts/commit-reviewed.sh -m x | git push",
  ]) assert.equal(runGate(command).status, 2, command);
});

// A throwaway repository with an origin/main ref, the real wrappers, and a stub `claude` that makes the review fail or pass.
function fixture({ claude }) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "precommit-review-test-"));
  const run = (cmd, args, extra = {}) => execFileSync(cmd, args, { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], ...extra });
  run("git", ["init", "-q", "-b", "main"]);
  run("git", ["config", "user.email", "t@example.invalid"]);
  run("git", ["config", "user.name", "t"]);
  fs.mkdirSync(path.join(root, "scripts"));
  for (const name of ["commit-reviewed.sh", "push-reviewed.sh", "precommit-review.sh"]) fs.copyFileSync(path.join(scripts, name), path.join(root, "scripts", name));
  fs.writeFileSync(path.join(root, "a.txt"), "base\n");
  run("git", ["add", "-A"]); run("git", ["commit", "-qm", "base"]);
  run("git", ["update-ref", "refs/remotes/origin/main", "HEAD"]);
  const bin = path.join(root, "bin");
  fs.mkdirSync(bin);
  fs.writeFileSync(path.join(bin, "claude"), claude, { mode: 0o755 });
  const env = { ...process.env, PATH: `${bin}:${process.env.PATH}` };
  return { root, env, run, sh: (script, args = []) => spawnSync("bash", [path.join(root, "scripts", script), ...args], { cwd: root, env, encoding: "utf8" }) };
}

const reviewer = (slopRating, slopFindings, defects) => `#!/usr/bin/env bash
agent=""; while [[ $# -gt 0 ]]; do [[ "$1" == "--agent" ]] && agent="$2"; shift; done
cat >/dev/null
if [[ "$agent" == "slop-reviewer" ]]; then body='{"rating":"${slopRating}","rationale":["a","b"],"findings":${slopFindings}}'
else body='{"signal":${defects !== "[]"},"findings":${defects}}'; fi
node -e 'console.log(JSON.stringify({result: "ok\\n\`\`\`json\\n" + process.argv[1] + "\\n\`\`\`"}))' "$body"
`;

test("commit-reviewed commits when both reviewers are clean and refuses otherwise", () => {
  const clean = fixture({ claude: reviewer("Low", "[]", "[]") });
  fs.writeFileSync(path.join(clean.root, "a.txt"), "changed\n");
  clean.run("git", ["add", "a.txt"]);
  const ok = clean.sh("commit-reviewed.sh", ["-m", "change"]);
  assert.equal(ok.status, 0, ok.stderr + ok.stdout);
  assert.equal(clean.run("git", ["log", "-1", "--format=%s"]).trim(), "change");

  const dirty = fixture({ claude: reviewer("Low", "[]", '[{"file":"a.txt","line":1,"severity":"low","confidence":0.9,"body":"bug"}]') });
  fs.writeFileSync(path.join(dirty.root, "a.txt"), "changed\n");
  dirty.run("git", ["add", "a.txt"]);
